<?php require 'config.php'; need(['doctor','receptionist','records']); check();
if(isset($_GET['print'])){$r=$pdo->prepare('SELECT r.*,p.first_name,p.last_name,p.patient_no,p.dob,p.gender FROM referrals r JOIN patients p ON p.id=r.patient_id WHERE r.id=?');$r->execute([(int)$_GET['print']]);$r=$r->fetch();if(!$r)die('Not found');
  echo '<body style="font:16px system-ui;max-width:700px;margin:30px auto"><h2>Referral letter</h2><p>To: <b>'.e($r['facility']).'</b><br>Date: '.substr($r['created_at'],0,10).' | Urgency: '.e($r['urgency']).'</p><p>Patient: <b>'.e($r['first_name'].' '.$r['last_name']).'</b> ('.e($r['patient_no']).'), '.e($r['gender']).', born '.e($r['dob']).'</p><p>Reason for referral:<br>'.nl2br(e($r['reason'])).'</p><p>Referred by: '.e(user()['name']).'</p><button onclick=print()>Print</button>';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(isset($_POST['status'])&&in_array($_POST['status'],['sent','received','closed']))$pdo->prepare('UPDATE referrals SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);
  else{$pdo->prepare('INSERT INTO referrals(patient_id,direction,facility,reason,urgency,created_by) VALUES(?,?,?,?,?,?)')->execute([(int)$_POST['patient'],$_POST['direction']=='in'?'in':'out',trim($_POST['facility']),trim($_POST['reason']),$_POST['urgency'],user()['id']]);audit('referral');}
  header('Location: referrals.php');exit;}
head('Referrals');$pts=$pdo->query('SELECT id,patient_no,first_name,last_name FROM patients ORDER BY id DESC LIMIT 200')->fetchAll();?>
<div class=card><h3>New referral</h3><form method=post class=g><?=field()?><div><label>Patient</label><select name=patient><?php foreach($pts as $p)echo '<option value='.$p['id'].'>'.e($p['patient_no'].' '.$p['first_name'].' '.$p['last_name']);?></select></div>
<div><label>Direction</label><select name=direction><option value=out>Referred out<option value=in>Referred in</select></div><div><label>Facility (to / from)</label><input name=facility required></div>
<div><label>Urgency</label><select name=urgency><option>routine<option>urgent<option>emergency</select></div><div style="grid-column:1/-1"><label>Reason and clinical summary</label><textarea name=reason required></textarea><button>Save referral</button></div></form></div>
<div class=card><table><tr><th>Patient<th>Direction<th>Facility<th>Urgency<th>Status<th></tr>
<?php foreach($pdo->query('SELECT r.*,p.first_name,p.last_name FROM referrals r JOIN patients p ON p.id=r.patient_id ORDER BY r.id DESC LIMIT 50') as $r):?>
<tr><td><?=e($r['first_name'].' '.$r['last_name'])?><td><?=$r['direction']?><td><?=e($r['facility'])?><td><?=$r['urgency']?><td><form method=post style="display:flex;gap:6px"><?=field()?><input type=hidden name=id value=<?=$r['id']?>><select name=status onchange=this.form.submit()><?php foreach(['sent','received','closed'] as $s)echo '<option'.($s==$r['status']?' selected':'').'>'.$s;?></select></form><td><a href="referrals.php?print=<?=$r['id']?>" target=_blank>Letter</a></tr><?php endforeach;?></table></div><?php foot();
